-- F35：SQL Durable Runtime。Worker 只通过受控函数领取 Job；Pi/渠道不持有 DB 凭证。
begin;
create table if not exists app.runtime_mission(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organization(id) on delete restrict,kind text not null,created_by uuid not null,created_at timestamptz not null default now());
create table if not exists app.runtime_run(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organization(id) on delete restrict,mission_id uuid not null references app.runtime_mission(id) on delete restrict,status text not null default 'queued' check(status in ('queued','running','completed','failed','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists app.runtime_job(id uuid primary key default gen_random_uuid(),organization_id uuid not null references app.organization(id) on delete restrict,run_id uuid not null references app.runtime_run(id) on delete restrict,idempotency_key text not null,kind text not null,priority integer not null default 0,attempts integer not null default 0,visible_at timestamptz not null default now(),lease_owner text,lease_expires_at timestamptz,status text not null default 'queued' check(status in ('queued','leased','completed','failed','cancelled')),last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,idempotency_key));
create index if not exists runtime_job_claim_idx on app.runtime_job(status,visible_at,priority desc,created_at);
create or replace function app.enqueue_runtime_job(input_run_id uuid,input_key text,input_kind text,input_priority integer default 0)
returns uuid language plpgsql security definer set search_path=app,pg_temp as $$ declare job_id uuid; begin
 if app.current_actor_id() is null then raise exception 'missing request context' using errcode='42501'; end if;
 if not exists(select 1 from app.runtime_run where id=input_run_id and organization_id=app.current_organization_id()) then raise exception 'run outside organization' using errcode='42501'; end if;
 insert into app.runtime_job(organization_id,run_id,idempotency_key,kind,priority) values(app.current_organization_id(),input_run_id,input_key,input_kind,input_priority) on conflict(organization_id,idempotency_key) do update set idempotency_key=excluded.idempotency_key returning id into job_id; return job_id; end $$;
create or replace function app.claim_runtime_job(input_owner text,input_lease_seconds integer default 30)
returns table(id uuid,run_id uuid,kind text,attempts integer) language plpgsql security definer set search_path=app,pg_temp as $$ begin
 return query with candidate as (select j.id from app.runtime_job j where j.organization_id=app.current_organization_id() and j.status='queued' and j.visible_at<=now() order by j.priority desc,j.created_at for update skip locked limit 1)
 update app.runtime_job j set status='leased',lease_owner=input_owner,lease_expires_at=clock_timestamp()+make_interval(secs=>input_lease_seconds),attempts=j.attempts+1,updated_at=clock_timestamp() from candidate where j.id=candidate.id returning j.id,j.run_id,j.kind,j.attempts; end $$;
create or replace function app.heartbeat_runtime_job(input_id uuid,input_owner text,input_lease_seconds integer default 30)
returns boolean language plpgsql security definer set search_path=app,pg_temp as $$ begin update app.runtime_job set lease_expires_at=clock_timestamp()+make_interval(secs=>input_lease_seconds),updated_at=clock_timestamp() where id=input_id and organization_id=app.current_organization_id() and status='leased' and lease_owner=input_owner and lease_expires_at>clock_timestamp(); return found; end $$;
create or replace function app.reap_runtime_jobs() returns integer language plpgsql security definer set search_path=app,pg_temp as $$ declare n integer; begin update app.runtime_job set status='queued',lease_owner=null,lease_expires_at=null,visible_at=clock_timestamp(),updated_at=clock_timestamp() where organization_id=app.current_organization_id() and status='leased' and lease_expires_at<=clock_timestamp(); get diagnostics n=row_count; return n; end $$;
create or replace function app.cancel_runtime_job(input_id uuid) returns boolean language plpgsql security definer set search_path=app,pg_temp as $$ begin update app.runtime_job set status='cancelled',updated_at=now() where id=input_id and organization_id=app.current_organization_id() and status in ('queued','leased'); return found; end $$;
alter table app.runtime_mission enable row level security; alter table app.runtime_mission force row level security; alter table app.runtime_run enable row level security; alter table app.runtime_run force row level security; alter table app.runtime_job enable row level security; alter table app.runtime_job force row level security;
do $$ declare t text; begin foreach t in array array['runtime_mission','runtime_run','runtime_job'] loop execute format('drop policy if exists %I on app.%I',t||'_isolation',t); execute format('create policy %I on app.%I for select to supplyagent_api using(organization_id=app.current_organization_id() and app.is_member(organization_id,app.current_actor_id()))',t||'_isolation',t); end loop; end $$;
drop policy if exists runtime_job_insert on app.runtime_job; drop policy if exists runtime_job_update on app.runtime_job;
create policy runtime_job_insert on app.runtime_job for insert to public with check(organization_id=app.current_organization_id()); create policy runtime_job_update on app.runtime_job for update to public using(organization_id=app.current_organization_id()) with check(organization_id=app.current_organization_id());
revoke all on app.runtime_mission,app.runtime_run,app.runtime_job from public; grant select on app.runtime_mission,app.runtime_run,app.runtime_job to supplyagent_api; grant execute on function app.enqueue_runtime_job(uuid,text,text,integer),app.claim_runtime_job(text,integer),app.heartbeat_runtime_job(uuid,text,integer),app.reap_runtime_jobs(),app.cancel_runtime_job(uuid) to supplyagent_api;
commit;
